basicHeaderGatherer <- function(txt = character(), max = NA) {
  basicTextGatherer(txt, max, parseHTTPHeader)
}

basicTextGatherer <- function(txt = character(), max = NA, value = NULL, .mapUnicode = TRUE) {
  update = function(str) {
    txt <<- c(txt, str)
    if(!is.na(max) && nchar(txt) >= max) {
      return(0)
    }

    nchar(str, "bytes")
  }

  reset = function() { 
    txt <<- character() 
  }

  val <- function(collapse = "") {
    if(!is.null(collapse))
      txt = paste(txt, collapse = collapse)
    if(.mapUnicode)
      txt = mapUnicodeEscapes(txt)
    value(txt)
  }

  ans <- structure(
    list(update = update, value = val, reset = reset),
    class = c("RCurlTextHandler", "RCurlCallbackFunction")  
  )
  ans$reset()
  ans
}
